#!/usr/bin/env python3
import os
import sqlite3
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote, urlsplit

DATA_DIR = "/var/lib/builder-app"
DATABASE = os.path.join(DATA_DIR, "records.sqlite3")


def initialize_database():
    os.makedirs(DATA_DIR, mode=0o755, exist_ok=True)
    with sqlite3.connect(DATABASE) as connection:
        connection.execute("PRAGMA synchronous=FULL")
        connection.execute(
            "CREATE TABLE IF NOT EXISTS records "
            "(id TEXT PRIMARY KEY, body BLOB NOT NULL)"
        )


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def _send(self, status, body=b"", content_type=None):
        self.send_response(status)
        if content_type is not None:
            self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if body:
            self.wfile.write(body)

    def _record_id(self):
        path = urlsplit(self.path).path
        prefix = "/records/"
        if not path.startswith(prefix):
            return None
        record_id = unquote(path[len(prefix):])
        if not record_id or "/" in record_id:
            return None
        return record_id

    def do_GET(self):
        if urlsplit(self.path).path == "/health":
            self._send(200, b"ready")
            return

        record_id = self._record_id()
        if record_id is None:
            self._send(404)
            return

        with sqlite3.connect(DATABASE) as connection:
            row = connection.execute(
                "SELECT body FROM records WHERE id = ?", (record_id,)
            ).fetchone()
        if row is None:
            self._send(404)
        else:
            self._send(200, bytes(row[0]))

    def do_PUT(self):
        record_id = self._record_id()
        if record_id is None:
            self._send(404)
            return

        try:
            length = int(self.headers["Content-Length"])
        except (TypeError, ValueError):
            self._send(411)
            return
        if length < 0:
            self._send(400)
            return
        body = self.rfile.read(length)
        if len(body) != length:
            self._send(400)
            return

        with sqlite3.connect(DATABASE) as connection:
            connection.execute(
                "INSERT INTO records(id, body) VALUES(?, ?) "
                "ON CONFLICT(id) DO UPDATE SET body = excluded.body",
                (record_id, body),
            )
            connection.commit()
        self._send(204)

    def log_message(self, format, *args):
        return


if __name__ == "__main__":
    initialize_database()
    server = ThreadingHTTPServer(("0.0.0.0", 8080), Handler)
    server.daemon_threads = True
    server.serve_forever()

